style.css:
@-moz-document domain("time.geekbang.org") {
/* 目录 */
  [class^="Syllabus_syllabusListWrapper"] {
    font-family: 方正黑体简体, 苹方-简, 微软雅黑, "Noto Sans CJK SC", sans-serif;
    max-height: unset;
    overflow-y: unset;
  }
  [class^="Syllabus_syllabusItem"] {
    margin-bottom: 12px
  }

  /* 课程标题 */
  [class^="Index_articleTitle"] {
    font-family: 方正大雅宋简体, 方正黑体简体, 苹方-简, 微软雅黑, "Noto Sans CJK SC", sans-serif;
  }

  /* 分级标题 */
  [data-slate-type="heading"] span[data-slate-string="true"] {
    font-family: 方正黑体简体, 苹方-简, 微软雅黑, "Noto Sans CJK SC", sans-serif;
  }

  /* 正文 */
  [data-slate-type="paragraph"] span[data-slate-string="true"] {
    font-family: 方正新书宋简体, 宋体-简, 华文宋体, 新宋体, "Noto Serif CJK SC", serif;
  }

  /* 列表 */
  div[data-slate-type="list-line"],
  div[data-slate-type="quote-line"] {
    font-family: 方正楷体简体, 华文楷体, 楷体, "Noto Serif CJK SC", serif;
    font-size: 15px;
    margin-bottom: 0;
  }
  div[data-code-line-number]::before {
    font-family: Georgia, serif;
  }
}
